@Component("quote-subscriber")
public class QuoteSubscriber extends BaseSubscriber {

	public QuoteSubscriber() {
	}
	
    public SubscriptionQueryResult<List<Quote>, Quote> quoteSubscribe() {
        return queryGateway
                .subscriptionQuery(new FindAllQuoteQuery(), 
                		ResponseTypes.multipleInstancesOf(Quote.class),
                		ResponseTypes.instanceOf(Quote.class));
    }

    public SubscriptionQueryResult<Quote, Quote> quoteSubscribe(@DestinationVariable UUID quoteId) {
        return queryGateway
                .subscriptionQuery(new FindQuoteQuery(new LoadQuoteFilter(quoteId)), 
                		ResponseTypes.instanceOf(Quote.class),
                		ResponseTypes.instanceOf(Quote.class));
    }





}

